// ---- sprites: assets/<pose>.webp next to this plugin, read on first use (keeps the module small and quick to load) ----
const spriteCache: Record<string, string> = {}
async function loadSprite($: any, key: string): Promise<string> {
  if (spriteCache[key] !== undefined) return spriteCache[key]
  try {
    const r = await $.fs.read(`${$.plugin.root}/assets/${key}.webp`, { as: 'bytes' })
    spriteCache[key] = r.base64
    return spriteCache[key]
  } catch (err) {
    return ''
  }
}
// the poses she is most likely to show first, read in the background right after the start
async function preloadSprites($: any) {
  for (const k of ['greet', 'idle', 'think', 'work', 'done']) await loadSprite($, k)
}

