// The four lines seen all day long (idle, work, think, done) are never the same twice in a row; the pick is kept for as long as the seed stays the same.
const NO_REPEAT = ['idle', 'work', 'think', 'done']
const lastPick: Record<string, { seed: number; text: string }> = {}
const say = (cat: string, lvl: number, seed: number, vars?: Record<string, string | number>) => {
  const arr = T[cat][stageOf(lvl)]
  const sd = Math.abs(Math.floor(seed))
  let i = sd % arr.length
  if (NO_REPEAT.includes(cat)) {
    const lp = lastPick[cat]
    if (lp && lp.seed === sd && arr.includes(lp.text)) i = arr.indexOf(lp.text)
    else {
      if (lp && arr[i] === lp.text) i = (i + 1) % arr.length
      lastPick[cat] = { seed: sd, text: arr[i] }
    }
  }
  let s = arr[i]
  if (vars) for (const k of Object.keys(vars)) s = s.split('{' + k + '}').join(String(vars[k]))
  return s
}
// time-of-day greeting for the first start of a day
const helloText = (lvl: number, hour: number) => {
  const slot = hour >= 5 && hour < 11 ? 0 : hour >= 11 && hour < 14 ? 1 : hour >= 14 && hour < 18 ? 2 : hour >= 18 ? 3 : 4
  return (T['hello' + stageOf(lvl)] as any)[slot][0] as string
}

// ---- lifetime counters ----
// Stats saved by an older version lack the newer fields: they count from 0.
const SUM_KEYS = ['turns', 'tools', 'pats', 'focus', 'night', 'pokes', 'compacts', 'breaks', 'errors', 'wakes', 'bursts', 'ignored'] as const
const MAX_KEYS = ['longest', 'peak'] as const
const normStats = (x?: Partial<Stats> | null): Stats => {
  const o: any = {}
  for (const k of SUM_KEYS) o[k] = Number((x as any)?.[k] ?? 0) || 0
  for (const k of MAX_KEYS) o[k] = Number((x as any)?.[k] ?? 0) || 0
  return o as Stats
}

// One store write at a time inside this conversation (two quick events must not read the same old value and both write).
// Never call a locked function from inside another one: it would wait for itself.
let lockTail: Promise<unknown> = Promise.resolve()
function locked<T>(fn: () => Promise<T>): Promise<T> {
  const run = lockTail.then(fn, fn)
  lockTail = run.then(() => undefined, () => undefined)
  return run
}

