// Poses with a closed-eye patch get it inside the SAME svg: the patch is faded in for a moment by the svg itself.
// (Swapping the whole svg for a blink restarted its bobbing animation, which looked like a jolt.)
const svgMemo: Record<string, string> = {}
const petSvg = (m: Sprite, img: string) => {
  const key = m + '|' + img.length
  if (svgMemo[key] !== undefined) return svgMemo[key]
  const bl = BLINK[m]
  const blink = bl
    ? `<image x="${bl.box[0]}" y="${bl.box[1]}" width="${bl.box[2]}" height="${bl.box[3]}" opacity="0" href="data:image/webp;base64,${bl.b}"><animate attributeName="opacity" values="0;0;1;1;0;0" keyTimes="0;0.90;0.905;0.945;0.95;1" dur="4.6s" repeatCount="indefinite"/></image>`
    : ''
  svgMemo[key] = `<svg xmlns="http://www.w3.org/2000/svg" width="96" height="105" viewBox="0 0 201 220"><g>${ANIM[m]}<image width="201" height="220" href="data:image/webp;base64,${img}"/>${blink}</g></svg>`
  return svgMemo[key]
}

const barColor = (p: number) => (p >= 85 ? '#ef4444' : p >= 60 ? '#f5b400' : '#22c55e')
const bar = (label: string, p: number | null, y: number, faded: boolean) => {
  const w = 170
  const f = p === null ? 0 : Math.max(0, Math.min(100, p))
  const txt = p === null ? '--' : `${p % 1 === 0 ? p : p.toFixed(1)}%`
  return (
    `<text x="0" y="${y + 10}" font-family="Consolas,Menlo,monospace" font-size="12" font-weight="600" fill="#8e8e93">${label}</text>` +
    `<rect x="34" y="${y}" width="${w}" height="12" rx="6" fill="#888" fill-opacity="0.3"/>` +
    (f > 0 ? `<rect x="34" y="${y}" width="${Math.max(12, (w * f) / 100)}" height="12" rx="6" fill="${barColor(f)}" fill-opacity="${faded ? 0.45 : 1}"/>` : '') +
    `<text x="${34 + w + 8}" y="${y + 10}" font-family="Consolas,Menlo,monospace" font-size="12" fill="#8e8e93">${txt}</text>`
  )
}
let barsKey = ''
let barsOut = ''
const barsSvg = (c: number | null, f5: number | null, f7: number | null, faded: boolean) => {
  const key = `${c}|${f5}|${f7}|${faded}`
  if (key !== barsKey) {
    barsKey = key
    barsOut = barsRaw(c, f5, f7, faded)
  }
  return barsOut
}
const barsRaw = (c: number | null, f5: number | null, f7: number | null, faded: boolean) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="262" height="64" viewBox="0 0 262 64">${bar('CTX', c, 4, false)}${bar('5H', f5, 26, faded)}${bar('7D', f7, 48, faded)}</svg>`

const dayOf = (ms: number) => {
  const d = new Date(ms)
  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`
}
// "2h13m" / "3d4h" / "<1m"; '--' when unknown or already past
const untilText = (iso: string | null, now: number) => {
  if (!iso) return '--'
  const ms = Date.parse(iso) - now
  if (!(ms > 0)) return '--'
  const m = Math.floor(ms / 60000)
  if (m >= 1440) return `${Math.floor(m / 1440)}d${Math.floor((m % 1440) / 60)}h`
  if (m >= 60) return `${Math.floor(m / 60)}h${m % 60}m`
  return m >= 1 ? `${m}m` : '<1m'
}

const POSE_MS: Partial<Record<PetMode, number>> = { done: DONE_FOR_MS, worry: 7000, greet: 8000, compact: 5 * 60 * 1000 }      // (compact: only a safety net; the compaction ends it itself)

async function setMode($: any, m: PetMode) {
  if ((await read($, mode)) === m) return          // already there: no write, so no redraw of the band
  const now = await $.clock.now()
  await update($, mode, () => m)
  await update($, since, () => now)
}

// a temporary pose (done / worry / greet) goes back to idle by itself
async function settleLater($: any, m: PetMode) {
  const ms = POSE_MS[m] ?? 0
  $.clock.after(ms + 400, async () => {
    const cur = await read($, mode)
    const t = await read($, since)
    const now = await $.clock.now()
    if (cur === m && now - t >= ms) await setMode($, 'idle')
  })
}

// a short message with its own pose, on top of whatever the pet is doing
async function flash($: any, text: string, sprite: Sprite, ms: number = FLASH_FOR_MS) {
  const now = await $.clock.now()
  await update($, flashText, () => text)
  await update($, flashSprite, () => sprite)
  await update($, reactKind, () => 'flash' as ReactKind)
  await update($, reactAt, () => now)
  const token = (await read($, reactToken)) + 1
  await update($, reactToken, () => token)
  $.clock.after(ms, async () => {
    if ((await read($, reactToken)) === token) await update($, reactKind, () => 'none' as ReactKind)
  })
}

// Which achievements are newly reached? Unlocking one can unlock another (the "all" one), so it repeats until nothing is new.
async function checkAchLocked($: any) {
  const stIn = (await $.store.get('stats')) as Partial<Stats> | undefined
  const s = normStats(stIn ?? (await read($, stats)))
  const skIn = (await $.store.get('streak')) as Streak | undefined
  const k = skIn && skIn.last ? skIn : await read($, streak)
  const aff = Math.max(Number((await $.store.get('affection')) ?? 0), await read($, affection))
  const lvl = levelOf(aff)
  const now = await $.clock.now()
  const tIn = (await $.store.get('today')) as Today | undefined
  const t = tIn && tIn.d === dayOf(now) ? tIn : await read($, today)
  const td: Today = t.d === dayOf(now) ? { d: t.d, turns: t.turns ?? 0, tools: t.tools ?? 0, pats: t.pats ?? 0, focus: t.focus ?? 0 } : { d: '', turns: 0, tools: 0, pats: 0, focus: 0 }
  const stored = (await $.store.get('achieved')) as string[] | undefined
  const mine = await read($, achieved)
  const known = Array.from(new Set(mine.concat(Array.isArray(stored) ? stored : [])))
  let have = known
  const fresh: Ach[] = []
  for (let round = 0; round < 5; round++) {
    const c: Ctx = { s, k, lvl, today: td, have }
    const next = ACHS.filter(a => !have.includes(a.id) && a.cur(c) >= a.goal)
    if (!next.length) break
    fresh.push(...next)
    have = have.concat(next.map(a => a.id))
  }
  if (fresh.length) {
    await update($, achieved, () => have)
    await $.store.set('achieved', have)
  } else if (have.length !== mine.length) {
    await update($, achieved, () => have)
  }
  return { fresh, lvl, total: have.length }
}

async function checkAch($: any) {
  const r = await locked(() => checkAchLocked($))
  if (!r.fresh.length) return
  const names = r.fresh.map(a => a.name)
  if (names.length > 3) {
    const line = `一口气解锁了 ${names.length} 个成就：${names.slice(0, 3).join('、')}等`
    $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
    await flash($, line, 'proud', 12000)
  } else {
    for (const n of names) $.ui.toast(say('ach', r.lvl, r.total, { a: n }), { timeoutMs: LONG_TOAST_MS })
    await flash($, say('ach', r.lvl, r.total, { a: names[0] }), 'proud', 12000)
  }
  const reward = r.fresh.reduce((n, a) => n + a.rw, 0)
  if (reward > 0) await addAffection($, reward)      // (this checks again, so an unlock caused by the reward is not missed)
}

async function addAffectionLocked($: any, n: number): Promise<number[]> {
  const stored = Number((await $.store.get('affection')) ?? 0)
  const before = Math.max(stored, await read($, affection))      // another conversation may have added points meanwhile
  const after = before + n
  await update($, affection, () => after)
  await $.store.set('affection', after)
  return [before, after]
}

async function addAffection($: any, n: number, check: boolean = true) {
  const [before, after] = await locked(() => addAffectionLocked($, n))
  const l0 = levelOf(before)
  const l1 = levelOf(after)
  if (l1 > l0) {
    const line = say('levelUp', l1, l1, { l: l1 })
    $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
    await flash($, line, ('up' + stageOf(l1)) as Sprite, LEVEL_UP_MS)
  }
  if (check) await checkAch($)
}

// today's counters (reset by themselves when the date changes), kept between runs
async function bumpTodayLocked($: any, turns: number, tools: number, pats: number, focus: number) {
  const now = await $.clock.now()
  const st = (await $.store.get('today')) as Today | undefined
  let t = st && st.d === dayOf(now) ? { d: st.d, turns: st.turns ?? 0, tools: st.tools ?? 0, pats: st.pats ?? 0, focus: st.focus ?? 0 } : await read($, today)
  if (t.d !== dayOf(now)) t = { d: dayOf(now), turns: 0, tools: 0, pats: 0, focus: 0 }
  t = { d: t.d, turns: t.turns + turns, tools: t.tools + tools, pats: t.pats + pats, focus: t.focus + focus }
  await update($, today, () => t)
  await $.store.set('today', t)
}

async function bumpToday($: any, turns: number, tools: number, pats: number, focus: number) {
  await locked(() => bumpTodayLocked($, turns, tools, pats, focus))
}

// lifetime counters: adds up (turns, tools, ...), or keeps the largest value (longest, peak)
async function bumpStatsLocked($: any, d: Partial<Stats>) {
  const ss = (await $.store.get('stats')) as Partial<Stats> | undefined
  const s = normStats(ss ?? (await read($, stats)))
  const n: any = { ...s }
  for (const k of SUM_KEYS) n[k] = s[k] + (Number(d[k] ?? 0) || 0)
  for (const k of MAX_KEYS) n[k] = Math.max(s[k], Number(d[k] ?? 0) || 0)
  await update($, stats, () => n as Stats)
  await $.store.set('stats', n)
}

// `check: false` when the caller checks the achievements itself once, after all of its counters (saves a few store reads per action)
async function bumpStats($: any, d: Partial<Stats>, check: boolean = true) {
  await locked(() => bumpStatsLocked($, d))
  if (check) await checkAch($)
}

// a click on one of the buttons: a short reaction on top of whatever the pet is doing
let recentPokes: number[] = []
async function react($: any, kind: 'pat' | 'poke') {
  const now = await $.clock.now()
  const wasAsleep = (await read($, mode)) === 'sleep'
  await update($, reactKind, () => kind)
  await update($, reactAt, () => now)
  const token = (await read($, reactToken)) + 1
  await update($, reactToken, () => token)
  if (wasAsleep) await setMode($, 'idle')
  if (kind === 'pat') {
    // today's pats are counted in the store: another conversation may have used some of the five already
    const st = (await $.store.get('today')) as Today | undefined
    const t = st && st.d === dayOf(now) ? st : await read($, today)
    const pats = t.d === dayOf(now) ? (t.pats ?? 0) : 0
    if (pats < PATS_PER_DAY) {
      await bumpToday($, 0, 0, 1, 0)
      await bumpStats($, { pats: 1 }, false)
      await addAffection($, 1)
    } else {
      await bumpStats($, { pats: 1 })
    }
  } else {
    recentPokes = recentPokes.filter(x => now - x < 10000)
    recentPokes.push(now)
    const burst = recentPokes.length >= 5
    if (burst) recentPokes = []
    await bumpStats($, { pokes: 1, wakes: wasAsleep ? 1 : 0, bursts: burst ? 1 : 0 })
  }
  $.clock.after(REACT_FOR_MS, async () => {
    if ((await read($, reactToken)) === token) await update($, reactKind, () => 'none' as ReactKind)
  })
}

// A usage warning appears once when the value crosses its limit, and can be dismissed; it is armed again when the value falls clearly below.
async function checkWarn($: any, kind: '5h' | 'ctx', v: number | null, limit: number, cycle?: string | null) {
  if (v === null) return
  if (kind === '5h' && v >= 95 && (await read($, stats)).peak === 0) await bumpStats($, { peak: 1 })
  const armed = kind === '5h' ? await read($, armed5) : await read($, armedC)
  if (v >= limit && armed) {
    const now = await $.clock.now()
    if (kind === '5h' && cycle) {
      // the 5H limit belongs to the account, not to this conversation: warn once per reset cycle across all conversations
      const cyc = Date.parse(cycle)
      const seen = Number((await $.store.get('warned5')) ?? 0)
      if (cyc > 0 && Math.abs(seen - cyc) < 10 * 60 * 1000) {
        await update($, armed5, () => false)
        return
      }
      await $.store.set('warned5', cyc)
    }
    const lvl = levelOf(await read($, affection))
    if (kind === '5h') await update($, armed5, () => false)
    else await update($, armedC, () => false)
    await update($, warnKind, () => kind)
    await update($, warnUntil, () => now + WARN_MS)
    $.ui.toast(say(kind === '5h' ? 'warn5h' : 'warnCtx', lvl, now / 1000), { timeoutMs: LONG_TOAST_MS })
  } else if (v < limit - 5 && !armed) {
    if (kind === '5h') await update($, armed5, () => true)
    else await update($, armedC, () => true)
  }
}

async function dismissWarn($: any) {
  await update($, warnKind, () => '' as '' | '5h' | 'ctx')
}

// "I have read it" on the one-hour reminder
async function dismissRemind($: any) {
  const now = await $.clock.now()
  const lvl = levelOf(await read($, affection))
  await update($, remindDue, () => false)
  await update($, nextRemind, () => now + REST_AFTER_MS)
  await flash($, say('restOk', lvl, now / 1000), 'greet')
}

// The "compact" button: puts /compact in the prompt box for the person to confirm (never sends it, never overwrites a draft)
async function fillCompact($: any) {
  let draft = ''
  try {
    draft = (await $.prompt.read()).text
  } catch (err) {
    draft = ''
  }
  if (draft.trim() !== '') {
    $.ui.toast('输入框里已经有内容了，先发送或清空，再点“压缩上下文”。', { timeoutMs: LONG_TOAST_MS })
    return
  }
  try {
    const r = await $.prompt.fill({ text: '/compact ' })
    $.ui.toast(r.isFilled ? '已填好 /compact，按回车开始压缩（也可以在后面写要保留什么）。' : '现在填不进输入框，请直接输入 /compact。', { timeoutMs: LONG_TOAST_MS })
  } catch (err) {
    $.ui.toast('现在填不进输入框，请直接输入 /compact。', { timeoutMs: LONG_TOAST_MS })
  }
}

async function startFocus($: any) {
  const now = await $.clock.now()
  const lvl = levelOf(await read($, affection))
  await update($, breakEnd, () => 0)      // a new timer ends the break
  await update($, focusEnd, () => now + FOCUS_MS)
  if ((await read($, mode)) === 'sleep') await setMode($, 'idle')      // starting a timer wakes her
  await flash($, say('focusStart', lvl, now / 1000), 'start')
  $.clock.after(FOCUS_MS + 500, async () => {
    await finishFocus($, now + FOCUS_MS)
  })
}

async function cancelFocus($: any) {
  const now = await $.clock.now()
  const lvl = levelOf(await read($, affection))
  await update($, focusEnd, () => 0)
  await flash($, say('focusCancel', lvl, now / 1000), 'giveup')
}

// called by the timer, and by the 30 s check in case the timer was lost in a reload
async function finishFocus($: any, endedAt: number) {
  if ((await read($, focusEnd)) !== endedAt) return
  const lvl = levelOf(await read($, affection))
  await update($, focusEnd, () => 0)
  if ((await $.clock.now()) - endedAt > LATE_FOCUS_MS) return      // the computer slept through it: no tomato for time that was not spent
  await bumpToday($, 0, 0, 0, 1)
  await bumpStats($, { focus: 1 }, false)
  await addAffection($, 2)
  $.ui.toast(say('focusDone', lvl, endedAt / 1000))
  await setMode($, 'done')
  await settleLater($, 'done')
  await startBreak($, Math.max(endedAt, await $.clock.now()))
}

// The break after a finished focus timer: only a new prompt, a new timer or the button end it early (patting and poking do not: that is not work).
async function startBreak($: any, now: number) {
  const end = now + BREAK_MS
  await update($, breakEnd, () => end)
  await update($, remindDue, () => false)
  await update($, nextRemind, () => end + REST_AFTER_MS)
  $.clock.after(BREAK_MS + 500, async () => {
    await finishBreak($, end)
  })
}

async function endBreak($: any) {
  await update($, breakEnd, () => 0)
}

// called by the timer, and by the 30 s check in case the timer was lost in a reload
async function finishBreak($: any, end: number) {
  if ((await read($, breakEnd)) !== end) return
  const lvl = levelOf(await read($, affection))
  await update($, breakEnd, () => 0)
  await update($, workStart, () => 0)      // a real rest: the hour of steady work starts over
  if (end !== demoBreakEnd) await bumpStats($, { breaks: 1 })      // (the /pet break demo is not counted)
  const line = say('breakDone', lvl, end / 1000)
  $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
  await flash($, line, 'greet', 8000)
}

// Counts the first use of a calendar day (a new session, or the first prompt of a session that stays open for days):
// time-of-day greeting, streak, a little affection. Returns the greeting, or null when today is already counted.
// the calendar day before `ms` (not "24 hours earlier": a day with a clock change is 23 or 25 hours long)
const dayBefore = (ms: number) => {
  const d = new Date(ms)
  d.setDate(d.getDate() - 1)
  return dayOf(d.getTime())
}

// `settleMs`: several conversations that start together (the app restarts with a few open) must not all count the same day:
// each writes a claim, waits that long, and only the one whose claim is still there goes on.
async function dailyCheck($: any, now: number, settleMs: number = 0): Promise<string | null> {
  const day = dayOf(now)
  const sk = (await $.store.get('streak')) as Streak | undefined
  const k = sk && sk.last ? sk : await read($, streak)
  if (k.last === day) {
    await update($, streak, () => k)
    return null
  }
  if (settleMs > 0) {
    const id = String(Math.random())
    await $.store.set('dayClaim', { d: day, id })
    await new Promise<void>(r => { $.clock.after(settleMs, () => r()) })
    const claim = (await $.store.get('dayClaim')) as { d: string; id: string } | undefined
    const again = (await $.store.get('streak')) as Streak | undefined
    if (!claim || claim.id !== id || (again && again.last === day)) {
      if (again && again.last) await update($, streak, () => again)
      return null
    }
  }
  const lvl = levelOf(await read($, affection))
  const n = k.last === dayBefore(now) ? k.n + 1 : 1
  const nk: Streak = { last: day, n, max: Math.max(k.max, n) }
  await update($, streak, () => nk)
  await $.store.set('streak', nk)
  let text = helloText(lvl, new Date(now).getHours())
  if (n >= 2) text += ' ' + say('streakLine', lvl, 0, { n })
  $.ui.toast(text)
  await addAffection($, 3 + Math.min(n - 1, 5))
  return text
}

// Restore what was saved and do the daily greeting. Runs in the background right after the session starts:
// session.start itself is awaited before the first prompt, so nothing slow may sit in it.
async function restoreSaved($: any) {
  try {
    const a = Number((await $.store.get('affection')) ?? 0)
    await update($, affection, () => a)
    const have = (await $.store.get('achieved')) as string[] | undefined
    if (Array.isArray(have)) await update($, achieved, () => have)
    const st = (await $.store.get('stats')) as Stats | undefined
    if (st) await update($, stats, () => normStats(st))
    const sk = (await $.store.get('streak')) as Streak | undefined
    if (sk) await update($, streak, () => sk)
    const saved = (await $.store.get('limits')) as { five?: { p: number; r?: string }; seven?: { p: number; r?: string } } | undefined
    const now0 = await $.clock.now()
    const alive = (x?: { p: number; r?: string }) => (x && x.r && Date.parse(x.r) > now0 ? x : null)
    const s5 = alive(saved?.five)
    const s7 = alive(saved?.seven)
    if (s5 || s7) {
      await update($, five, () => (s5 ? s5.p : null))
      await update($, seven, () => (s7 ? s7.p : null))
      await update($, fiveReset, () => (s5 && s5.r ? s5.r : null))
      await update($, sevenReset, () => (s7 && s7.r ? s7.r : null))
      await update($, stale, () => true)
    }
    const ch = await $.store.get('cacheHit')
    if (typeof ch === 'number') {
      await update($, cacheHit, () => ch)
      await update($, cacheOld, () => true)
    }
    const td = (await $.store.get('today')) as Today | undefined
    if (td && td.d === dayOf(now0)) await update($, today, () => ({ d: td.d, turns: td.turns ?? 0, tools: td.tools ?? 0, pats: td.pats ?? 0, focus: td.focus ?? 0 }))

    // first use of a day: time-of-day greeting, streak, a little affection; otherwise a short "welcome back"
    const daily = await dailyCheck($, now0, 150)
    const greeting = daily ?? say('greetBack', levelOf(await read($, affection)), now0 / 1000)
    await update($, greetText, () => greeting)
  } catch (err) {
    // keep going with defaults
  }
}

// /pet <what>: shows how a notification looks (nothing is counted)
// declared once, when the session starts
async function registerDemo($: any) {
  try {
    await $.command.register({ name: 'pet', description: '演示桌宠的提醒和姿势', argumentHint: '[long|rest|ach|hello|focus|break|compact|warn|level|start|cancel|version]' })
  } catch (err) {
    // the demo command is optional
  }
}

async function demo($: any, what: string): Promise<string> {
  const lvl = levelOf(await read($, affection))
  const now = await $.clock.now()
  if (what === 'long') {
    const line = say('longDone', lvl, now / 1000, { m: 5 })
    $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
    await flash($, line, 'long', 60000)
    return '演示：长任务完成（姿势保持 1 分钟，或到下一次发消息）'
  }
  if (what === 'rest') {
    $.ui.toast(say('rest', lvl, now / 1000), { timeoutMs: LONG_TOAST_MS })
    await update($, remindDue, () => true)
    return '演示：连续工作提醒（出现“知道啦”按钮，点它就消失）'
  }
  if (what === 'ach') {
    const line = say('ach', lvl, 1, { a: '示例成就' })
    $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
    await flash($, line, 'proud', 12000)
    return '演示：成就'
  }
  if (what === 'hello') {
    const line = helloText(lvl, new Date(now).getHours()) + ' ' + say('streakLine', lvl, 0, { n: 3 })
    $.ui.toast(line)
    await flash($, line, 'greet', 8000)
    return '演示：每日问候'
  }
  if (what === 'warn') {
    $.ui.toast(say('warn5h', lvl, now / 1000), { timeoutMs: LONG_TOAST_MS })
    await update($, warnKind, () => '5h' as '' | '5h' | 'ctx')
    await update($, warnUntil, () => now + 60000)
    return '演示：额度提醒（担心姿势带眨眼，点“知道啦”消失，1 分钟后自动恢复）'
  }
  if (what.startsWith('level')) {
    const n = Math.max(2, Math.min(MAX_LEVEL, parseInt(what.slice(5).trim(), 10) || lvl))
    const line = say('levelUp', n, n, { l: n })
    $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
    await flash($, line, ('up' + stageOf(n)) as Sprite, LEVEL_UP_MS)
    return '演示：升到 Lv.' + n + '（用法：/pet level 7 可以看别的等级的姿势）'
  }
  if (what === 'start' || what === 'cancel') {
    const line = say(what === 'start' ? 'focusStart' : 'focusCancel', lvl, now / 1000)
    await flash($, line, what === 'start' ? 'start' : 'giveup')
    return '演示：' + (what === 'start' ? '番茄钟开始' : '放弃专注')
  }
  if (what === 'compact') {
    await setMode($, 'compact')
    $.clock.after(15000, async () => {
      if ((await read($, mode)) !== 'compact') return
      await setMode($, 'idle')
      const line = say('compactDone', levelOf(await read($, affection)), now / 1000)
      $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
      await flash($, line, 'done', 8000)
    })
    return '演示：压缩中 15 秒，然后显示整理完毕'
  }
  if (what === 'version') return '桌宠 ' + BUILD_INFO
  if (what === 'break') {
    const end = now + 60000
    demoBreakEnd = end
    await update($, breakEnd, () => end)
    $.clock.after(60500, async () => { await finishBreak($, end) })
    return '演示：休息 1 分钟（发消息、点“结束休息”或开新番茄钟会提前结束，摸头和戳一下不会）'
  }
  if (what === 'focus') {
    $.ui.toast(say('focusDone', lvl, now / 1000))
    await flash($, say('focusDone', lvl, now / 1000), 'done', 8000)
    return '演示：番茄钟结束'
  }
  $.ui.toast('这就是弹出提示的样子，会停留 10 秒。', { timeoutMs: LONG_TOAST_MS })
  return '用法：/pet long | rest | ach | hello | focus | break | compact | warn | level | start | cancel | version（只是演示，不计入任何统计）'
}

export const register: Register = on => {
  let toolsThisTurn = 0

  on('session.start', async ($, e, next) => {
    // Pose and timers first: they are quick, and nothing below may stop the greeting if the hook runs out of time
    await setMode($, 'greet')
    await settleLater($, 'greet')
    // every 30 s: sleep after a quiet spell, end timed poses, the one-hour reminder, a finished focus timer
    $.clock.every(30000, async () => {
      const m = await read($, mode)
      const t = await read($, since)
      const now = await $.clock.now()
      const focusing = (await read($, focusEnd)) > 0      // she keeps you company during a focus timer instead of dozing off
      if (m === 'idle' && !focusing && now - t > SLEEP_AFTER_MS) await setMode($, 'sleep')
      const lim = POSE_MS[m]
      if (lim !== undefined && now - t > lim) await setMode($, 'idle')
      const ws = await read($, workStart)
      const la = await read($, lastActive)
      const nr = await read($, nextRemind)
      if (ws > 0 && now - la > WORK_GAP_MS) {
        await update($, workStart, () => 0)
        await update($, remindDue, () => false)
      } else if (ws > 0 && now >= nr && !(await read($, remindDue))) {
        await update($, remindDue, () => true)
        $.ui.toast(say('rest', levelOf(await read($, affection)), now / 1000), { timeoutMs: LONG_TOAST_MS })
      }
      const fe = await read($, focusEnd)
      if (fe > 0 && now >= fe) await finishFocus($, fe)
      const be = await read($, breakEnd)
      if (be > 0 && now >= be) await finishBreak($, be)
      const wu = await read($, warnUntil)
      if (wu > 0 && now >= wu) {
        await update($, warnKind, () => '' as '' | '5h' | 'ctx')
        await update($, warnUntil, () => 0)
      }
    })
    // every minute: redraw so the countdowns move
    $.clock.every(60000, async () => {
      await update($, tick, n => n + 1)
    })
    await registerDemo($)
    // restore saved data in the background (see restoreSaved)
    $.clock.after(10, () => preloadSprites($))
    $.clock.after(30, () => restoreSaved($))
    return next(e)
  })

  on('command.run', { command: 'pet' }, async ($, e) => {
    return { text: await demo($, e.args.trim()) }
  })

  on('turn.start', async ($, e, next) => {
    const now = await $.clock.now()
    if (await read($, remindDue)) await bumpStats($, { ignored: 1 })      // the break reminder is on and the person carries on
    const ws = await read($, workStart)
    const la = await read($, lastActive)
    if (ws === 0 || now - la > WORK_GAP_MS) {
      await update($, workStart, () => now)
      await update($, nextRemind, () => now + REST_AFTER_MS)
      await update($, remindDue, () => false)
    }
    await update($, lastActive, () => now)
    await endBreak($)      // sending a prompt means back to work
    await update($, reactKind, v => (v === 'flash' ? ('none' as ReactKind) : v))      // a held pose ends with the next prompt
    const hello = await dailyCheck($, now)          // a session left open overnight still counts the new day
    if (hello) await flash($, hello, 'greet')
    await setMode($, 'think')
    return next(e)
  })

  // The pet only asks "waiting for you" when the permission dialog really goes to the person.
  // (tool.check answering 'ask' is NOT that: in Auto mode it just means "a model classifier decides",
  // which made the pet look like it was waiting almost all the time.)
  on('classic.PermissionRequest', async ($, e, next) => {
    await setMode($, 'wait')
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    toolsThisTurn += 1
    if (e.tool === 'AskUserQuestion') {
      await setMode($, 'wait')
      const r = await next(e)
      await setMode($, 'work')
      return r
    }
    await setMode($, 'work')
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId) return next(e)
    const tools = toolsThisTurn
    toolsThisTurn = 0
    const now = await $.clock.now()
    await update($, lastActive, () => now)
    if (e.usage) {
      const u = e.usage
      const total = u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
      if (total > 0) {
        const r = (await read($, cacheRead)) + u.cache_read_input_tokens
        const a = (await read($, cacheAll)) + total
        await update($, cacheRead, () => r)
        await update($, cacheAll, () => a)
        const hit = Math.round((100 * r) / a)
        await update($, cacheHit, () => hit)
        await update($, cacheOld, () => false)
        if (hit !== lastHit) {
          lastHit = hit
          await $.store.set('cacheHit', hit)
        }
      }
    }
    if (e.reason === 'answer') {
      const lvl = levelOf(await read($, affection))
      await bumpToday($, 1, tools, 0, 0)
      const hour = new Date(now).getHours()
      await bumpStats($, { turns: 1, tools, night: hour < 5 ? 1 : 0, longest: e.durationMs }, false)
      await addAffection($, 1)
      await setMode($, 'done')
      await settleLater($, 'done')
      if (e.durationMs >= LONG_TURN_MS) {
        const longLine = say('longDone', lvl, now / 1000, { m: Math.max(1, Math.round(e.durationMs / 60000)) })
        $.ui.toast(longLine, { timeoutMs: LONG_TOAST_MS })
        await flash($, longLine, 'long', LONG_HOLD_MS)
      }
    } else if (e.reason === 'error') {
      await setMode($, 'worry')
      await settleLater($, 'worry')
      await bumpStats($, { errors: 1 })
    } else {
      await setMode($, 'idle')
    }
    return next(e)
  })

  // While a compaction runs (the person's /compact, the engine's own at its threshold, the button's): the pet shows it.
  // The silent "precompute" runs and subagents' own compactions are not shown.
  on('session.compact', async ($, e, next) => {
    if (e.trigger === 'precompute' || e.agentId) return next(e)
    const before = await read($, mode)
    await setMode($, 'compact')
    try {
      const r = await next(e)
      const lvl = levelOf(await read($, affection))
      if (r.skip !== undefined) {
        await setMode($, before === 'compact' ? 'idle' : before)
      } else {
        const now = await $.clock.now()
        const line = say('compactDone', lvl, now / 1000)
        $.ui.toast(line, { timeoutMs: LONG_TOAST_MS })
        await setMode($, 'idle')
        await flash($, line, 'done', 8000)
        await bumpStats($, { compacts: 1 })
      }
      return r
    } catch (err) {
      await setMode($, 'idle')
      throw err
    }
  })

  on('session.measure', async ($, e, next) => {
    const f = (k: string) => e.rateLimits.find(r => r.kind === k)
    if (e.changed.includes('context')) {
      const cp = e.context.percent ?? null
      if ((await read($, ctx)) !== cp) await update($, ctx, () => cp)
      await checkWarn($, 'ctx', e.context.percent ?? null, WARN_CTX)
    }
    if (e.changed.includes('cost') && e.cost && (await read($, cost)) !== e.cost.usd) await update($, cost, () => e.cost!.usd)
    if (e.changed.includes('rateLimits')) {
      const f5 = f('five_hour')
      const f7 = f('seven_day')
      const n5 = f5 ? f5.percentUsed : null
      const n7 = f7 ? f7.percentUsed : null
      const r5 = f5 && f5.resetsAt ? f5.resetsAt : null
      const r7 = f7 && f7.resetsAt ? f7.resetsAt : null
      if ((await read($, five)) !== n5) await update($, five, () => n5)
      if ((await read($, seven)) !== n7) await update($, seven, () => n7)
      if ((await read($, fiveReset)) !== r5) await update($, fiveReset, () => r5)
      if ((await read($, sevenReset)) !== r7) await update($, sevenReset, () => r7)
      if (await read($, stale)) await update($, stale, () => false)
      await checkWarn($, '5h', f5 ? f5.percentUsed : null, WARN_5H, f5 ? f5.resetsAt : null)
      const lim = {
        five: f5 ? { p: f5.percentUsed, r: f5.resetsAt } : undefined,
        seven: f7 ? { p: f7.percentUsed, r: f7.resetsAt } : undefined,
      }
      const limKey = JSON.stringify(lim)
      if (limKey !== lastLimits) {
        lastLimits = limKey
        await $.store.set('limits', lim)
      }
    }
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const [m, t, hidden, aff, c, f5, f7] = [
      await read($, mode), await read($, since), await read($, isHidden), await read($, affection),
      await read($, ctx), await read($, five), await read($, seven),
    ]
    const faded = await read($, stale)
    const lvl = levelOf(aff)

    if (hidden) {
      return (
        <Box>
          <Button key="show" label="显示桌宠" plain dimColor onPress={() => update($, isHidden, () => false)} />
        </Box>
      )
    }

    const rk = await read($, reactKind)
    const rAt = await read($, reactAt)
    const due = await read($, remindDue)
    const fe = await read($, focusEnd)
    const wk = await read($, warnKind)
    const wu = await read($, warnUntil)
    const warn = wk !== '' && (await $.clock.now()) < wu
    const quiet = m === 'idle' || m === 'sleep' || m === 'greet'
    const base: PetMode = (m === 'idle' && warn) ? 'worry' : m
    let shown: Sprite = rk === 'pat' ? (lvl >= 14 ? 'heart' : 'shy') : rk === 'poke' ? 'surprised' : rk === 'flash' ? await read($, flashSprite) : base
    const be = await read($, breakEnd)
    if (rk === 'none' && quiet && (due || be > 0)) shown = 'rest'
    else if (rk === 'none' && m === 'idle' && fe > 0) shown = 'focus'

    // the line: reactions first, then reminders and warnings, then the focus timer, then the state's own line
    let line = m === 'greet' ? '' : say(m, lvl, Math.floor(t / 1000))      // 'greet' has no line table: its text is chosen at start
    if (m === 'greet') line = (await read($, greetText)) || say('greetBack', lvl, 0)
    else if (m === 'idle' && fe > 0) line = say('focusLine', lvl, Math.floor(t / 60000))
    if (quiet && be > 0) line = say('breakLine', lvl, Math.floor(t / 60000))
    if (quiet && warn) line = say(wk === '5h' ? 'warn5h' : 'warnCtx', lvl, Math.floor(wu / 60000))
    if (due) line = say('rest', lvl, Math.floor((await read($, nextRemind)) / 60000))
    if (rk === 'pat' || rk === 'poke') line = say(rk, lvl, Math.floor(rAt / 1000))
    else if (rk === 'flash') line = await read($, flashText)

    const now = await $.clock.now()
    const r5 = await read($, fiveReset)
    const r7 = await read($, sevenReset)
    const hit = await read($, cacheHit)
    const hitOld = await read($, cacheOld)
    const usd = await read($, cost)
    const td = await read($, today)
    const have = await read($, achieved)
    const open = await read($, showAch)
    const og = await read($, openGroup)
    const sameDay = td.d === dayOf(now)
    await read($, tick)
    const breakLeft = be > 0 ? Math.max(1, Math.ceil((be - now) / 60000)) : 0
    const sum = await read($, showSum)
    const sk = await read($, streak)
    const stt = await read($, stats)
    const focusLeft = fe > 0 ? Math.max(1, Math.ceil((fe - now) / 60000)) : 0
    const nextAt = lvl >= MAX_LEVEL ? 0 : THRESH[lvl]
    const heart = lvl >= MAX_LEVEL ? `♥ Lv.${lvl} MAX` : `♥ Lv.${lvl} · ${aff}`

    const heartText = lvl >= MAX_LEVEL ? `♥ Lv.${lvl} MAX` : `♥ Lv.${lvl} · ${aff}/${nextAt}`
    const gone = sameDay ? td : { d: '', turns: 0, tools: 0, pats: 0, focus: 0 }
    const achCtx: Ctx = { s: normStats(stt), k: sk, lvl, today: gone, have }

    const sumBtn = <Button key="sum" label={`今日 ${gone.turns} 轮 · ${gone.tools} 工具 · ${gone.focus} 番茄 ${sum ? '▾' : '▸'}`} plain dimColor onPress={() => { update($, showSum, v => !v); update($, showAch, () => false) }} />
    const achBtn = <Button key="ach" label={`成就 ${have.length}/${ACHS.length} ${open ? '▾' : '▸'}`} plain dimColor onPress={() => { update($, showAch, v => !v); update($, showSum, () => false) }} />
    const btnRow = (
      <Box flexDirection="row" gap={2} flexWrap={e.surface === 'desktop' ? 'nowrap' : 'wrap'}>
        <Button key="pat" label="摸摸头" plain dimColor onPress={() => react($, 'pat')} />
        <Button key="poke" label="戳一下" plain dimColor onPress={() => react($, 'poke')} />
        {be > 0
          ? null      // during the break the row shows "结束休息" instead (keeps the row as short as while a timer runs)
          : fe > 0
            ? <Button key="focus" label={`放弃专注 · 剩 ${focusLeft} 分`} plain dimColor onPress={() => cancelFocus($)} />
            : <Button key="focus" label="专注 25 分钟" plain dimColor onPress={() => startFocus($)} />}
        {c !== null && c >= COMPACT_BTN_AT && m !== 'compact' ? <Button key="compact" label="压缩上下文" plain dimColor onPress={() => fillCompact($)} /> : null}
        {be > 0 ? <Button key="brk" label={`结束休息 · 剩 ${breakLeft} 分`} plain dimColor onPress={() => endBreak($)} /> : null}
        {due ? <Button key="rest" label="知道啦" plain onPress={() => dismissRemind($)} /> : null}
        {warn && !due ? <Button key="warnok" label="知道啦" plain onPress={() => dismissWarn($)} /> : null}
        {e.surface === 'desktop' ? null : sumBtn}
        {e.surface === 'desktop' ? null : achBtn}
        <Button key="hide" label="隐藏" plain dimColor onPress={() => update($, isHidden, () => true)} />
      </Box>
    )
    const sumPanel = sum ? (
      <Box flexDirection="column" paddingX={2}>
        <Text>{`今日小结　${say('summary', lvl, Math.floor(now / 86400000))}`}</Text>
        <Text dimColor>{`· 对话 ${gone.turns} 轮，调用工具 ${gone.tools} 次`}</Text>
        <Text dimColor>{`· 番茄钟 ${gone.focus} 个（专注 ${gone.focus * 25} 分钟）　摸摸头 ${gone.pats} 次`}</Text>
        <Text dimColor>{`· 连续使用 ${sk.n} 天（最长 ${sk.max} 天）　好感度 Lv.${lvl}`}</Text>
        <Text dimColor>{`· 累计 ${stt.turns} 轮 · ${stt.tools} 工具 · ${stt.focus} 番茄 · 最长一次任务 ${Math.round(stt.longest / 60000)} 分钟`}</Text>
      </Box>
    ) : null
    const achPanel = open ? (
      <Box flexDirection="column" paddingX={2}>
        <Box flexDirection="row" flexWrap="wrap" gap={2}>
          {GROUPS.map(g => {
            const all = ACHS.filter(a => a.g === g.id)
            const got = all.filter(a => have.includes(a.id)).length
            return <Button key={'ag-' + g.id} label={`${og === g.id ? '▾' : '▸'} ${g.name} ${got}/${all.length}`} plain dimColor={og !== g.id} onPress={() => update($, openGroup, v => (v === g.id ? '' : g.id))} />
          })}
        </Box>
        {og === '' ? <Text dimColor>点上面的分类，看已解锁和未解锁的成就。</Text> : null}
        {ACHS.filter(a => a.g === og && have.includes(a.id)).map(a => <Text key={a.id}>{`✓ ${a.name}　${a.desc}　+${a.rw}♥`}</Text>)}
        {ACHS.filter(a => a.g === og && !a.hid && !have.includes(a.id)).map(a => (
          <Text key={a.id} dimColor>{`· ${a.name}　${a.desc}${a.goal > 1 ? `　${Math.min(a.cur(achCtx), a.goal)}/${a.goal}` : ''}　+${a.rw}♥`}</Text>
        ))}
        {og !== '' && ACHS.filter(a => a.g === og && a.hid && !have.includes(a.id)).length > 0
          ? <Text dimColor>{`？ 还有 ${ACHS.filter(a => a.g === og && a.hid && !have.includes(a.id)).length} 个隐藏成就等你发现`}</Text>
          : null}
      </Box>
    ) : null

    // no pictures here (the terminal draws no Svg): one text line, the same buttons, the same panels
    if (e.surface !== 'desktop') {
      const n = (v: number | null) => (v === null ? '--' : `${v}%`)
      return (
        <Box flexDirection="column">
          <Text wrap="truncate">{`(${m}) ${line} · CTX ${n(c)} · 5H ${n(f5)} · 7D ${n(f7)} · ♥Lv.${lvl}`}</Text>
          {btnRow}
          {sumPanel}
          {achPanel}
        </Box>
      )
    }

    const sprite = (await loadSprite($, shown)) || (await loadSprite($, 'work'))      // a pose whose picture is not drawn yet falls back to 'work'

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" alignItems="center" gap={1} paddingX={1}>
          <Svg source={petSvg(shown, sprite)} alt={`pet: ${shown}`} width={96} height={105} />
          <Box flexDirection="column" gap={0}>
            <Svg source={barsSvg(c, f5, f7, faded)} alt="usage bars" width={262} height={64} />
            <Box flexDirection="row" gap={2}>
              <Text wrap="truncate">{line}</Text>
              <Box flexShrink={0}><Text dimColor wrap="truncate">{heartText}</Text></Box>
            </Box>
            {btnRow}
          </Box>
          {e.props.bodyColumns < NARROW_COLS ? null : <Box flexDirection="row" gap={3} marginLeft={1} flexShrink={0}>
            <Box flexDirection="column" gap={0} flexShrink={0}>
              <Text dimColor wrap="truncate">{`5H 重置 ${untilText(r5, now)}`}</Text>
              <Text dimColor wrap="truncate">{`7D 重置 ${untilText(r7, now)}`}</Text>
              <Text dimColor wrap="truncate">{`缓存 ${hit === null ? '--' : hit + '%'}${hitOld ? '*' : ''}`}</Text>
            </Box>
            <Box flexDirection="column" gap={0} flexShrink={0}>
              <Text dimColor wrap="truncate">{`本会话 ${usd === null ? '--' : '$' + usd.toFixed(2)}`}</Text>
              {sumBtn}
              {achBtn}
            </Box>
          </Box>}
        </Box>
        {sumPanel}
        {achPanel}
      </Box>
    )
  })
}
